task count_Unset_Bits(n: int) returns (r: int)
  requires n >= 0
  ensures r == sum(i in [1, n] . count_unset_bits(i))
{
  r := 0;
  var i: int := 1;
  while i <= n
    invariant 1 <= i and i <= n + 1
    invariant r == sum(j in [1, i - 1] . count_unset_bits(j))
    decreases n + 1 - i
  {
    var c: int := count_unset_bits(i);
    r := r + c;
    i := i + 1;
  }
}

func count_unset_bits(k: int) returns (c: int)
{
  c := 0;
  var j: int := k;
  while j > 0
    invariant c + j == k + 1
    invariant c >= 0
    decreases j
  {
    if j % 2 == 0 {
      c := c + 1;
    }
    j := j / 2;
  }
}
